        )
        
        case 4: return .erase(id: try FfiConverterUInt32.read(from: &buf), slot: try FfiConverterTypeFfiSlot.read(from: &buf)
        )
        
        case 5: return .wrap(id: try FfiConverterUInt32.read(from: &buf), plaintext: try FfiConverterData.read(from: &buf)
        )
        
